        MOD = 10 ** 9 + 7

        def comb(a, b):
            if b < 0 or b > a:
                return 0
            b = min(b, a - b)
            res = 1
            for i in range(1, b + 1):
                res = res * (a - b + i) % MOD * pow(i, MOD - 2, MOD) % MOD
            return res

        ans = []
        for n, k in queries:
            res = 1
            d = 2
            while d * d <= k:
                if k % d == 0:
                    e = 0
                    while k % d == 0:
                        k //= d
                        e += 1
                    res = res * comb(e + n - 1, n - 1) % MOD
                d += 1
            if k > 1:
                res = res * comb(n, n - 1) % MOD
            ans.append(res)
        return ans

