    static long long power(long long b, long long e) {
        long long r = 1;
        b %= MOD;
        while (e) {
            if (e & 1) r = r * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return r;
    }

    static long long comb(long long a, long long b) {
        if (b < 0 || b > a) return 0;
        b = min(b, a - b);
        long long res = 1;
        for (long long i = 1; i <= b; ++i)
            res = res * ((a - b + i) % MOD) % MOD * power(i, MOD - 2) % MOD;
        return res;
    }

public:
    vector<int> waysToFillArray(vector<vector<int>>& queries) {
        vector<int> ans;
        ans.reserve(queries.size());
        for (auto& qr : queries) {
