                    long long e = 0;
                    while (k % d == 0) { k /= d; ++e; }
                    res = res * comb(e + n - 1, n - 1) % MOD;
                }
            }
            if (k > 1) res = res * comb(n, n - 1) % MOD;
            ans.push_back((int)res);
