class Solution {
    private static final long MOD = 1_000_000_007L;
    private static final int MAXF = 10015, V = 10001;
    private static final long[] FACT = new long[MAXF];
    private static final long[] INV_FACT = new long[MAXF];
    private static final int[] SPF = new int[V];

    private static void precompute() {
        FACT[0] = 1;
        for (int i = 1; i < MAXF; i++) FACT[i] = FACT[i - 1] * i % MOD;
        INV_FACT[MAXF - 1] = power(FACT[MAXF - 1], MOD - 2);
        for (int i = MAXF - 1; i > 0; i--) INV_FACT[i - 1] = INV_FACT[i] * i % MOD;
        for (int v = 2; v < V; v++)
            if (SPF[v] == 0)
                for (int j = v; j < V; j += v)
                    if (SPF[j] == 0) SPF[j] = v;
    }

    private static long power(long b, long e) {
        long r = 1;
        b %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return r;
    }

    public int[] waysToFillArray(int[][] queries) {
        if (FACT[0] == 0) precompute();
        int[] ans = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int n = queries[qi][0], k = queries[qi][1];
            long res = 1;
            while (k > 1) {
                int p = SPF[k], e = 0;
                while (k % p == 0) { k /= p; e++; }
                res = res * FACT[e + n - 1] % MOD * INV_FACT[n - 1] % MOD * INV_FACT[e] % MOD;
            }
            ans[qi] = (int) res;
        }
        return ans;
    }
}

